  { id: "ca-green-gables", country: "ca", name: "Green Gables, Cavendish", name_zh: "卡文迪什 · 绿山墙", lat: 46.491667, lon: -63.385, place_type: "prototype", prototype_of: "《绿山墙的安妮》里卡斯伯特家绿色山墙农舍的原型。房子属于蒙哥马利外祖父的表亲，她小时候常在屋后的田野、“鬼树林”和“情人小径”里游荡。如今由加拿大国家公园管理局照小说里的样子布置，是蒙哥马利卡文迪什国家历史遗址的中心", prototype_of_en: "The green-gabled farmhouse of the Cuthberts in Anne of Green Gables. It belonged to cousins of Montgomery's grandfather, and as a girl she roamed its fields, the Haunted Wood and Lover's Lane behind it. Parks Canada keeps it furnished as the novel describes, at the heart of the L. M. Montgomery's Cavendish National Historic Site", coord_checked: "Category:Green Gables (Prince Edward Island) (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Green_Gables_(Prince_Edward_Island), 2026-11-17", photo: {"file": "images/places/ca-green-gables.jpg", "width": 800, "height": 450, "author": "Robert Linsdell from St. Andrews, Canada", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File%3AGreen_Gables_Heritage_Place%2C_Cavendish_%28471127%29_%289450685350%29.jpg", "alt_en": "The green-gabled farmhouse at Green Gables Heritage Place, Cavendish", "alt_zh": "卡文迪什绿山墙故居的绿色山墙农舍"} },
  { id: "ca-montgomery-home", country: "ca", name: "L. M. Montgomery's Cavendish Home", name_zh: "蒙哥马利卡文迪什故居", lat: 46.489399, lon: -63.37727, place_type: "pilgrimage", note: "蒙哥马利 1876 到 1911 年和外祖父母同住的农舍旧址，她就在厨房窗前写出了《绿山墙的安妮》。如今只剩石头地基和老苹果园，由外祖父母家的后人照看，离绿山墙走路不远", book_ids: ["anne-of-green-gables", "emily-of-new-moon"], note_en: "The site of the farmhouse where Montgomery lived with her grandparents from 1876 to 1911 and wrote Anne of Green Gables at the kitchen window. Only the stone foundations and the old apple orchard remain; her grandparents' descendants still look after the site, a short walk from Green Gables", coord_checked: "Category:L.M. Montgomery's Cavendish (Wikimedia Commons), the national historic site that includes the home site — https://commons.wikimedia.org/wiki/Category:L.M._Montgomery%27s_Cavendish, 2026-11-17", photo: {"file": "images/places/ca-montgomery-home.jpg", "width": 800, "height": 536, "author": "CP Hoffman from Washington, DC, United States", "license": "CC BY-SA 2.0", "license_url": "https://creativecommons.org/licenses/by-sa/2.0", "source": "https://commons.wikimedia.org/wiki/File%3AFoundation_of_Old_Farmhouse_%28L._M._Montgomery_childhood_home%29%2C_Cavendish_%283639608263%29.jpg", "alt_en": "Stone foundations of the farmhouse where Montgomery lived with her grandparents", "alt_zh": "蒙哥马利与外祖父母同住的农舍留下的石头地基"} },
  { id: "ca-cape-breton", country: "ca", name: "Cape Breton, Inverness County", name_zh: "布雷顿角 · 因弗内斯县", lat: 46.2303, lon: -61.3064, place_type: "original", note: "布雷顿角岛西岸，18 世纪 70 年代起由苏格兰高地人开垦，至今讲盖尔语的人家不少。《没有大碍》写的是“红发卡勒姆的家族”：1779 年卡勒姆·麦克唐纳从莫伊达特渡海在这里上岸。如今卡伯特小径和凯利小径沿岸而行，夏天乡间礼堂里到处是小提琴音乐", note_en: "The Gaelic-speaking west coast of Cape Breton Island, settled from the 1770s by Highland Scots. No Great Mischief follows the clann Chalum Ruaidh, the descendants of red-haired Calum MacDonald, who landed here from Moidart in 1779. Today the Cabot Trail and the Ceilidh Trail run along this shore, with fiddle music in the halls all summer", coord_checked: "Category:Inverness, Nova Scotia (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Inverness,_Nova_Scotia, 2026-11-17", photo: {"file": "images/places/ca-cape-breton.jpg", "width": 800, "height": 587, "author": "Z3lvs", "license": "CC0", "license_url": "http://creativecommons.org/publicdomain/zero/1.0/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3APleasant_Bay%2C_the_village_and_the_Cabot_Trail_below_the_switchbacks%2C_Cape_Breton_Highlands_National_Park%2C_Nova_Scotia.jpg", "alt_en": "The Cabot Trail above Pleasant Bay, Inverness County, Cape Breton", "alt_zh": "布雷顿角因弗内斯县普莱森特湾上方的卡伯特小径"} },
  { id: "ca-montreal", country: "ca", name: "Montreal", name_zh: "蒙特利尔", lat: 45.503343, lon: -73.586841, place_type: "original", note: "一座讲法语的城市，城里讲英语的少数派两百年来住在皇家山坡上，隔着几条街，也隔着一整种文化。休·麦克伦南把这道鸿沟称作“两种孤独”——取自里尔克的诗句，加拿大人至今还在用。里奇勒笔下的巴尼·帕诺夫斯基也在这座城里喝酒、吵架、过完一生；他的《所罗门·古尔斯基到此一游》里，从私酒贩子变成威士忌大亨的古尔斯基三兄弟，在皇家山坡上比邻盖起了石砌豪宅", note_en: "A French-speaking city with an English-speaking minority that for two centuries lived on the slopes of Mount Royal, a few streets and a whole culture away. Hugh MacLennan named the divide 'two solitudes', a phrase from Rilke that Canadians still use. Mordecai Richler's Barney Panofsky drinks and quarrels his way through the same city, and in his Solomon Gursky Was Here the three Gursky brothers, bootleggers turned whisky barons, build neighbouring fieldstone mansions on the slope of Mount Royal", coord_checked: "Category:Montreal (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Montreal, 2026-11-17", photo: {"file": "images/places/ca-montreal.jpg", "width": 800, "height": 532, "author": "Jiaqian AirplaneFan", "license": "CC BY 3.0", "license_url": "https://creativecommons.org/licenses/by/3.0", "source": "https://commons.wikimedia.org/wiki/File%3AView_of_downtown_Montreal_and_Mount_Royal-panoramio.jpg", "alt_en": "Downtown Montreal and Mount Royal", "alt_zh": "蒙特利尔市中心和皇家山"} },
  { id: "ca-cypress-massacre", country: "ca", name: "Cypress Hills Massacre site, Fort Walsh", name_zh: "沃尔什堡 · 塞浦路斯丘大屠杀遗址", lat: 49.549722, lon: -109.889167, place_type: "original", note: "1873 年 6 月，一群美国猎狼人和私酒贩子在塞浦路斯丘法韦尔贸易站旁袭击了纳科达（阿西尼博因）人的营地，杀死二十多人。这场屠杀促成了西北骑警的建立，他们 1875 年在附近修起沃尔什堡。重建的堡垒和屠杀遗址都由加拿大国家公园管理局开放", note_en: "In June 1873 American wolf hunters and whisky traders attacked a camp of Nakoda (Assiniboine) people beside Farwell's trading post in the Cypress Hills and killed more than twenty. The killings hastened the founding of the North-West Mounted Police, who built Fort Walsh nearby in 1875. Parks Canada runs both the rebuilt fort and the massacre site", coord_checked: "Category:Cypress Hills Massacre (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Cypress_Hills_Massacre, 2026-11-17", photo: {"file": "images/places/ca-cypress-massacre.jpg", "width": 800, "height": 600, "author": "Drm310", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AFort_Walsh_2013.jpg", "alt_en": "Fort Walsh in the Cypress Hills", "alt_zh": "塞浦路斯丘中的沃尔什堡"} },
  { id: "ca-kingston-pen", country: "ca", name: "Kingston Penitentiary", name_zh: "金斯顿监狱", lat: 44.219444, lon: -76.513611, place_type: "original", note: "加拿大最古老的监狱，1835 年建在安大略湖岸，2013 年关闭。十六岁的女仆格蕾丝·马克斯因 1843 年雇主和管家被杀一案被判刑，在这里关了近三十年；《别名格蕾丝》想象她在典狱长家里向一位年轻医生讲述往事。如今有导览带游客走过牢房", note_en: "Canada's oldest prison, opened in 1835 on the shore of Lake Ontario and closed in 2013. Grace Marks, a sixteen-year-old servant convicted of the 1843 murders of her employer and his housekeeper, spent nearly thirty years here, and Alias Grace imagines her talking to a young doctor in the governor's house. Guided tours now take visitors through the cell blocks", coord_checked: "Category:Kingston Penitentiary (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Kingston_Penitentiary, 2026-11-17", photo: {"file": "images/places/ca-kingston-pen.jpg", "width": 800, "height": 275, "author": "P199", "license": "Public domain", "license_url": "https://creativecommons.org/publicdomain/mark/1.0/", "source": "https://commons.wikimedia.org/wiki/File%3AKingston_Pen_2.JPG", "alt_en": "Kingston Penitentiary from Lake Ontario in winter", "alt_zh": "冬天从安大略湖上看金斯顿监狱"} },
  { id: "ca-toronto", country: "ca", name: "Toronto", name_zh: "多伦多", lat: 43.670278, lon: -79.386667, place_type: "original", note: "加拿大第一大城，在安大略湖北岸，也是加拿大小说写得最多的地方。《战争》里的罗伯特·罗斯从这里奔赴战壕，阿特伍德的叙述者在这里长大、结婚、哀悼，从《盲刺客》的艾丽丝·蔡斯到《证言》里的黛西；罗伯逊·戴维斯笔下的博伊·斯汤顿也被发现死在这里的港口。《猫眼》里阿特伍德的画家伊莱恩·里斯利回到这里办回顾展，《放血与奇迹疗法》里林伟健笔下的年轻医生在这里的急诊室熬过非典，斯科特·皮尔格林则在这座城的大街小巷里迎战拉蒙娜·弗劳尔斯的邪恶前任。从多伦多群岛回望，整条湖岸尽收眼底", note_en: "Canada's largest city, on the north shore of Lake Ontario, and the setting of more Canadian novels than any other place. Robert Ross leaves from here for the trenches in The Wars, Atwood's narrators grow up, marry and grieve here, from The Blind Assassin's Iris Chase to The Testaments' Daisy, and Robertson Davies's Boy Staunton is found dead in its harbour. Atwood's painter Elaine Risley comes home to it for a retrospective in Cat's Eye, Vincent Lam's young doctors work its emergency rooms through SARS in Bloodletting & Miraculous Cures, and Scott Pilgrim fights Ramona Flowers's evil exes across its streets. The view back from the Toronto Islands takes in the whole waterfront", coord_checked: "Category:Toronto (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Toronto, 2026-11-17", photo: {"file": "images/places/ca-toronto.jpg", "width": 800, "height": 355, "author": "Jchmrt", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ASunset_Toronto_Skyline_Panorama_Crop_from_Snake_Island.jpg", "alt_en": "The Toronto skyline at sunset from the Toronto Islands", "alt_zh": "日落时从多伦多群岛看多伦多天际线"} },
  { id: "ca-lake-laberge", country: "ca", name: "Lake Laberge", name_zh: "拉伯奇湖", lat: 61.169444, lon: -135.169444, place_type: "original", note: "育空河在白马市北边展开成的一段湖面，长约 50 公里，就在当年通往道森的淘金水路上。在白马当银行职员的罗伯特·瑟维斯让它出了名：《萨姆·麦吉的火化》里，叙述者就在拉伯奇湖畔兑现了对冻死的朋友许下的诺言。冬天湖面冻得结实，夏天有人钓鱼划船", note_en: "A 50-kilometre widening of the Yukon River north of Whitehorse, on the old gold-rush route to Dawson. Robert Service, a bank clerk in Whitehorse, made it famous as 'the marge of Lake Lebarge' where the narrator of 'The Cremation of Sam McGee' keeps his promise to a frozen friend. It freezes hard in winter and is fished and paddled in summer", coord_checked: "Category:Lake Laberge (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Lake_Laberge, 2026-11-17", photo: {"file": "images/places/ca-lake-laberge.jpg", "width": 800, "height": 533, "author": "Diego Delso", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ALago_Laberge%2C_Yuk%C3%B3n%2C_Canad%C3%A1%2C_2017-08-26%2C_DD_162.jpg", "alt_en": "Lake Laberge, Yukon", "alt_zh": "育空的拉伯奇湖"} },
  { id: "ca-service-cabin", country: "ca", name: "Robert Service Cabin, Dawson City", name_zh: "道森城 · 瑟维斯小屋", lat: 64.055854, lon: -139.430626, place_type: "pilgrimage", note: "道森城第八大道上的两间小木屋。罗伯特·瑟维斯 1909 到 1912 年住在这里，那时他已因《淘金汉之歌》成名，在这里写出了淘金热小说。加拿大国家公园管理局保留了原样，夏天有演员在门廊上朗诵他的叙事诗", book_ids: ["songs-of-a-sourdough"], note_en: "The two-room log cabin on Eighth Avenue where Robert Service lived from 1909 to 1912, already famous for Songs of a Sourdough, and wrote his novel of the gold rush. Parks Canada keeps it as he left it, and in summer actors read his ballads on the porch", coord_checked: "Category:Robert Service Cabin (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Robert_Service_Cabin, 2026-11-17", photo: {"file": "images/places/ca-service-cabin.jpg", "width": 800, "height": 536, "author": "George Dean", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3ARobert_Service%27s_Cabin_Dawson_City_-_panoramio.jpg", "alt_en": "Robert Service's log cabin in Dawson City", "alt_zh": "道森城罗伯特·瑟维斯的小木屋"} },
  { id: "ca-dawson", country: "ca", name: "Dawson City", name_zh: "道森城", lat: 64.060751, lon: -139.431674, place_type: "original", note: "克朗代克淘金热的首府：1898 年约有三万人挤在克朗代克河口的这座小城。杰克·伦敦 1897 年在上游的斯图尔特河过冬，《野性的呼唤》和《白牙》都写到了道森的酒馆和街道。小城至今保留着假门面的木楼、木板人行道和土路", note_en: "The capital of the Klondike gold rush: in 1898 some 30,000 people crowded into it at the mouth of the Klondike River. Jack London wintered on the Stewart River, upstream, in 1897, and both The Call of the Wild and White Fang come to Dawson's saloons and streets. The town keeps its false-front buildings, wooden sidewalks and dirt roads", coord_checked: "Category:Dawson City (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Dawson_City, 2026-11-17", photo: {"file": "images/places/ca-dawson.jpg", "width": 800, "height": 474, "author": "Unknown", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AMen_in_front_of_the_stores_in_Front_Street%2C_Dawson%2C_Yukon_%28J6246%29.jpg", "alt_en": "Men in front of the stores on Front Street, Dawson, in the gold-rush years", "alt_zh": "淘金热年代道森前街商店门口的人们"} },
  { id: "ca-birchtown", country: "ca", name: "Birchtown, Shelburne", name_zh: "谢尔本 · 伯奇敦", lat: 43.744444, lon: -65.3825, place_type: "original", note: "1783 年由约 1500 名黑人效忠派建立。他们逃离奴役为英军作战，战后从纽约撤来这里，伯奇敦一度是北美最大的自由黑人定居点。《黑人之书》里，阿米娜塔·迪亚洛在这里熬过几个饥寒的冬天，1792 年再乘船去塞拉利昂。黑人效忠派文化遗产中心讲述他们的故事", note_en: "Founded in 1783 by some 1,500 Black Loyalists, people who had escaped slavery to fight for the British and were evacuated from New York, it was the largest free Black settlement in North America. In The Book of Negroes Aminata Diallo lives through its hungry winters before sailing for Sierra Leone in 1792. The Black Loyalist Heritage Centre tells their story", coord_checked: "Birchtown, Nova Scotia (Wikipedia) — https://en.wikipedia.org/wiki/Birchtown,_Nova_Scotia, 2026-11-17", photo: {"file": "images/places/ca-birchtown.jpg", "width": 800, "height": 387, "author": "Madereugeneandrew", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ABirchtown%2C_Nova_Scotia_%28cropped%29.jpg", "alt_en": "The heritage trail sign at Birchtown", "alt_zh": "伯奇敦的历史步道指示牌"} },
  { id: "ca-wingham", country: "ca", name: "Wingham, Ontario", name_zh: "安大略 · 温厄姆", lat: 43.8874, lon: -81.3104, place_type: "prototype", prototype_of: "艾丽丝·门罗小说里朱比利、汉拉蒂等小镇的原型。门罗 1931 年生在这里，在镇边长大，父亲养银狐；《女孩和女人的生活》（1971）里，德尔·乔丹在朱比利镇外弗拉茨路尽头父亲的狐狸场上长大，《你以为你是谁？》（1978）里的罗丝则在西汉拉蒂长大。镇上有以她命名的文学花园和博物馆展室", prototype_of_en: "Jubilee, Hanratty and the other small towns of Alice Munro's stories. Munro was born here in 1931 and grew up on the edge of town, where her father kept silver foxes; in Lives of Girls and Women (1971) Del Jordan grows up on her father's fox farm at the end of the Flats Road outside Jubilee, and in Who Do You Think You Are? (1978) Rose grows up in West Hanratty. The town has a literary garden and a museum display in her name", coord_checked: "Category:Wingham, Ontario (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Wingham,_Ontario, 2026-11-17", photo: {"file": "images/places/ca-wingham.jpg", "width": 800, "height": 428, "author": "Unknown photographer", "license": "Public domain", "license_url": "https://creativecommons.org/publicdomain/mark/1.0/", "source": "https://commons.wikimedia.org/wiki/File%3APhotograph_of_Josephine_Street_in_Wingham%2C_Ontario%2C_Canada%2C_1909.jpg", "alt_en": "Josephine Street, Wingham, in 1909", "alt_zh": "1909 年的温厄姆约瑟芬街"} },
  { id: "ca-manitouwadge", country: "ca", name: "Manitouwadge", name_zh: "马尼托瓦奇", lat: 49.1333, lon: -85.8333, place_type: "original", note: "安大略西北丛林里的矿业小镇，建于 20 世纪 50 年代。《印第安马》里，从寄宿学校活下来的奥吉布瓦冰球天才索尔十三岁来到这里，加入全是奥吉布瓦人的“马尼托瓦奇驼鹿队”，沿横加公路在各个小镇冰场比赛。这里至今是冰球小镇", note_en: "A mining town in the bush of northwestern Ontario, built in the 1950s. In Indian Horse, Saul, a gifted Ojibway hockey player who has survived a residential school, comes here at thirteen to play for the Manitouwadge Moose, an all-Ojibway team touring the small rinks along the Trans-Canada Highway. It is still a hockey town", coord_checked: "Category:Manitouwadge, Ontario (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Manitouwadge,_Ontario, 2026-11-17" },
  { id: "ca-tyndall", country: "ca", name: "Tyndall, Manitoba", name_zh: "曼尼托巴 · 廷代尔", lat: 50.07716, lon: -96.65789, place_type: "original", note: "温尼伯以东的采石小村，渥太华国会大厦那种带斑纹的石灰岩就叫“廷代尔石”。《斯通家史札记》从这里开始：1905 年，戴西·古德威尔生在一个石匠家里，母亲当天就死了。采石场至今仍在开采", note_en: "A quarry village east of Winnipeg that gave its name to Tyndall stone, the mottled limestone of the Parliament buildings in Ottawa. The Stone Diaries begins here in 1905, when Daisy Goodwill is born in a stonecutter's house and her mother dies the same day. The quarries are still worked", coord_checked: "Commons photo 'St. Michael’s Ukrainian Catholic Curches Memorial, Tyndall, Manitoba 02', camera location 50.07716, -96.65789 — https://commons.wikimedia.org/wiki/File:St._Michael’s_Ukrainian_Catholic_Curches_Memorial,_Tyndall,_Manitoba_02.jpg, 2026-11-17", photo: {"file": "images/places/ca-tyndall.jpg", "width": 800, "height": 702, "author": "Clematisflower", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ASt._Michael%E2%80%99s_Ukrainian_Catholic_Curches_Memorial%2C_Tyndall%2C_Manitoba_01.jpg", "alt_en": "St. Michael's church memorial in Tyndall, built of the local limestone", "alt_zh": "廷代尔用本地石灰岩砌成的圣米迦勒教堂纪念建筑"} },
  { id: "ca-thamesville", country: "ca", name: "Thamesville, Ontario", name_zh: "安大略 · 塔姆斯维尔", lat: 42.551667, lon: -81.977222, place_type: "prototype", prototype_of: "《第五项业务》里德普特福德的原型。罗伯逊·戴维斯 1913 年生在泰晤士河边的这座小镇；小说里，1908 年 12 月有人在这里扔出一个裹着石头的雪球，砸中了牧师怀孕的妻子，从此把三个男孩的一生缠在一起六十年。", prototype_of_en: "Deptford in Fifth Business. Robertson Davies was born in this small town on the Thames River in 1913; in the novel a snowball with a stone in it, thrown here in December 1908, hits the preacher's pregnant wife and binds three boys' lives together for sixty years.", coord_checked: "Category:Thamesville (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Thamesville, 2026-11-17", photo: {"file": "images/places/ca-thamesville.jpg", "width": 800, "height": 600, "author": "P199", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3AThamesville_ON.JPG", "alt_en": "The main street of Thamesville", "alt_zh": "塔姆斯维尔的主街"} },
  { id: "ca-steinbach", country: "ca", name: "Steinbach, Manitoba", name_zh: "曼尼托巴 · 斯坦巴克", lat: 49.5258, lon: -96.6839, place_type: "prototype", prototype_of: "《复杂的善意》里东村的原型。这座草原小镇 1874 年由门诺派移民建立，米丽娅姆·托尤斯在这里长大；十六岁的诺米·尼克尔讲述的那个严苛的小社区就以它为样本，而她的母亲和姐姐都已先后离开。门诺派文化遗产村博物馆展示着移民的房屋和风车", prototype_of_en: "East Village in A Complicated Kindness. Founded by Mennonite settlers in 1874, the prairie town where Miriam Toews grew up is the model for the strict, small community that sixteen-year-old Nomi Nickel narrates, after her mother and sister have both disappeared from it. The Mennonite Heritage Village museum shows the settlers' houses and windmill", coord_checked: "Category:Steinbach, Manitoba (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Steinbach,_Manitoba, 2026-11-17", photo: {"file": "images/places/ca-steinbach.jpg", "width": 800, "height": 600, "author": "Robert Linsdell from St. Andrews, Canada", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File%3AMennonite_Heritage_Village%2C_Steinbach_%28441289%29_%289442976439%29.jpg", "alt_en": "A thatched-roof house at the Mennonite Heritage Village, Steinbach", "alt_zh": "斯坦巴克门诺派文化遗产村的茅草顶房屋"} },
  { id: "ca-winnipeg", country: "ca", name: "Winnipeg", name_zh: "温尼伯", lat: 49.886944, lon: -97.130556, place_type: "original", note: "红河与阿西尼博因河在“岔口”交汇处的草原城市，这里六千年来都是人们相聚的地方。米丽娅姆·托尤斯把《我所有渺小的哀伤》放在这里：约莉一次次飞回家，陪伴不想再活下去的天才钢琴家姐姐埃尔芙。岔口市场和河边步道是全城聚会的地方", note_en: "The prairie city where the Red and Assiniboine rivers meet, at The Forks, a meeting place for six thousand years. Miriam Toews set All My Puny Sorrows here: Yoli flies home again and again to her sister Elf, a brilliant pianist who no longer wants to live. The Forks market and river walk are the city's gathering place", coord_checked: "Category:The Forks (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:The_Forks, 2026-11-17", photo: {"file": "images/places/ca-winnipeg.jpg", "width": 800, "height": 572, "author": "Ethan Sahagun", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AEsplanade_Riel_Bridge_at_dusk%2C_Winnipeg%2C_Canada.jpg", "alt_en": "The Esplanade Riel bridge at The Forks, Winnipeg, at dusk", "alt_zh": "黄昏时温尼伯岔口的里尔步行桥"} },
  { id: "ca-lakefield", country: "ca", name: "Lakefield, Ontario", name_zh: "安大略 · 莱克菲尔德", lat: 44.4236, lon: -78.2736, place_type: "prototype", prototype_of: "《占卜者》里麦康奈尔码头的原型。玛格丽特·劳伦斯晚年住在奥托纳比河边的这个村子；她笔下的女作家莫拉格·冈恩住在河边的木屋里，常在心里和凯瑟琳·帕尔·特雷尔争论——这位拓荒作家 19 世纪 30 年代和妹妹苏珊娜·穆迪一起在附近定居。", prototype_of_en: "McConnell's Landing in The Diviners. Margaret Laurence spent her last years in this Otonabee River village, and Morag Gunn, her novelist heroine, lives in a log house on the river and argues in her head with Catharine Parr Traill, the pioneer writer who settled near here in the 1830s beside her sister Susanna Moodie.", coord_checked: "Category:Lakefield, Ontario (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Lakefield,_Ontario, 2026-11-17", photo: {"file": "images/places/ca-lakefield.jpg", "width": 800, "height": 444, "author": "Suzanne Schroeter", "license": "CC BY-SA 2.0", "license_url": "https://creativecommons.org/licenses/by-sa/2.0", "source": "https://commons.wikimedia.org/wiki/File%3AOtonabee_River%2C_Lakefield_%285399471125%29.jpg", "alt_en": "The Otonabee River at Lakefield", "alt_zh": "莱克菲尔德的奥托纳比河"} },
  { id: "ca-craigellachie", country: "ca", name: "Craigellachie", name_zh: "克雷盖拉奇", lat: 50.9753, lon: -118.724, place_type: "original", note: "鹰隘里的一片空地。1885 年 11 月 7 日，唐纳德·史密斯在这里敲下加拿大太平洋铁路的最后一颗道钉，把蒙特利尔和太平洋连在一起。皮埃尔·伯顿的《最后一颗道钉》以那张著名照片收尾。横加公路旁的铁轨边立着纪念石堆和一座小站房", note_en: "A clearing in Eagle Pass where on 7 November 1885 Donald Smith drove the last spike of the Canadian Pacific Railway, joining Montreal to the Pacific. Pierre Berton's The Last Spike ends with the famous photograph of that moment. A cairn and a small station stand beside the tracks off the Trans-Canada Highway", coord_checked: "Category:Last Spike (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Last_Spike, 2026-11-17", photo: {"file": "images/places/ca-craigellachie.jpg", "width": 800, "height": 533, "author": "Dietmar Rabich", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ACraigellachie_%28BC%2C_Canada%29%2C_The_Last_Spike%2C_Denkmal_--_2022_--_2186.jpg", "alt_en": "The Last Spike cairn at Craigellachie", "alt_zh": "克雷盖拉奇的最后一颗道钉纪念石堆"} },
  { id: "ca-discovery-claim", country: "ca", name: "Discovery Claim, Bonanza Creek", name_zh: "博南扎溪 · 发现地", lat: 63.9168, lon: -139.317, place_type: "original", note: "1896 年 8 月 16 日，乔治·卡马克、斯库库姆·吉姆（基什）和道森·查理在这条当时叫“兔溪”的小溪里发现了金子，引发了克朗代克淘金热。在道森长大的皮埃尔·伯顿在《克朗代克》里讲了这段故事。如今在挖金船留下的碎石堆中间，有加拿大国家公园管理局的步道和标牌指出最初的矿权地", note_en: "On 16 August 1896 George Carmack, Skookum Jim (Keish) and Dawson Charlie found gold in this creek, then called Rabbit Creek, setting off the Klondike Gold Rush. Pierre Berton, who grew up in Dawson, told the story in Klondike. A Parks Canada trail with signs marks the original claim among the dredge tailings", coord_checked: "Category:Discovery Claim (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Discovery_Claim, 2026-11-17", photo: {"file": "images/places/ca-discovery-claim.jpg", "width": 800, "height": 600, "author": "JKBrooks85", "license": "Public domain", "license_url": "https://creativecommons.org/publicdomain/mark/1.0/", "source": "https://commons.wikimedia.org/wiki/File%3ADiscovery_Claim_Bonanza_Creek.jpg", "alt_en": "Bonanza Creek at the Discovery Claim", "alt_zh": "发现地的博南扎溪"} },
  { id: "ca-ucluelet", country: "ca", name: "Ucluelet", name_zh: "尤克卢利特", lat: 48.935, lon: -125.541944, place_type: "original", note: "温哥华岛西岸的渔村。1899 年，年轻的画家埃米莉·卡尔住在这里的教会，努查努尔特人给她起名“克利·维克”，意思是“爱笑的人”；她这本书的第一篇就写这件事。如今这里是托菲诺比较安静的邻居，在环太平洋国家公园边上", note_en: "A fishing village on the west coast of Vancouver Island. In 1899 the young painter Emily Carr stayed at the mission here, and the Nuu-chah-nulth people named her Klee Wyck, 'Laughing One'; the first story of her book tells how. Today it is the quieter neighbour of Tofino, at the edge of Pacific Rim National Park", coord_checked: "Category:Ucluelet (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Ucluelet, 2026-11-17", rough_coast: true, photo: {"file": "images/places/ca-ucluelet.jpg", "width": 800, "height": 600, "author": "Tourism Ucluelet", "license": "Public domain", "license_url": "https://creativecommons.org/publicdomain/mark/1.0/", "source": "https://commons.wikimedia.org/wiki/File%3AInnerHarbour.JPG", "alt_en": "Ucluelet's inner harbour", "alt_zh": "尤克卢利特的内港"} },
  { id: "ca-carr-house", country: "ca", name: "Emily Carr House, Victoria", name_zh: "维多利亚 · 埃米莉·卡尔故居", lat: 48.4138, lon: -123.37, place_type: "pilgrimage", note: "维多利亚詹姆斯湾的一座意大利式住宅，埃米莉·卡尔 1871 年生在这里，在这里长大，后来写进了《小家伙之书》。这位画西海岸森林和村落的画家晚年因病不能作画，才开始写作，《克利·维克》获得 1941 年总督文学奖。故居现为博物馆", book_ids: ["klee-wyck"], note_en: "The Italianate house in James Bay where Emily Carr was born in 1871 and grew up, and which she described in The Book of Small. Carr, painter of the West Coast forests and villages, took up writing late, when illness kept her from painting; Klee Wyck won the Governor General's Award in 1941. The house is a museum", coord_checked: "Category:Emily Carr House (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Emily_Carr_House, 2026-11-17", photo: {"file": "images/places/ca-carr-house.jpg", "width": 800, "height": 533, "author": "dronepicr", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File%3AHouse_of_Emily_Carr_%2843814592065%29.jpg", "alt_en": "Emily Carr House in Victoria", "alt_zh": "维多利亚的埃米莉·卡尔故居"} },
  { id: "ca-granby", country: "ca", name: "Granby, Quebec", name_zh: "魁北克 · 格兰比", lat: 45.4, lon: -72.733333, place_type: "original", note: "东部镇区的一座小工业城，1979 年接纳了越南船民。十岁的金翠和家人从马来西亚难民营来到这里；她用短小片段写成的《小溪》，把接纳他们的这座小城回忆成第一个天堂。格兰比也以动物园和布瓦文湖出名", note_en: "A small industrial city in the Eastern Townships that took in Vietnamese boat people in 1979. Kim Thúy, ten years old, arrived here with her family from a Malaysian refugee camp, and Ru, her book of short fragments, remembers the town that welcomed them as a first paradise. Granby is also known for its zoo and Lake Boivin", coord_checked: "Category:Granby, Quebec (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Granby,_Quebec, 2026-11-17", photo: {"file": "images/places/ca-granby.jpg", "width": 800, "height": 532, "author": "Gabriel Picard", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ARue_Principale_Granby_2023-1_%28cropped%29.jpg", "alt_en": "Rue Principale in Granby", "alt_zh": "格兰比的主街"} },
  { id: "ca-miramichi", country: "ca", name: "Miramichi River valley", name_zh: "米拉米奇河谷", lat: 47.0225, lon: -65.508889, place_type: "original", note: "新不伦瑞克东北部的鲑鱼河和纸浆厂一带，戴维·亚当斯·理查兹生在这里，几乎所有小说都写这里。《孩子们中的怜悯》里，西德尼·亨德森小时候以为自己害死了一个玩伴，从此发誓永不还手，他的家人却要为此付出代价。这条河以大西洋鲑鱼垂钓闻名", note_en: "The salmon river and pulp-mill country of northeastern New Brunswick, where David Adams Richards was born and sets nearly all his novels. In Mercy Among the Children Sydney Henderson, who as a boy believed he had killed a playmate, vows never to strike back, and his family pays for it. The river is famous for Atlantic salmon fishing", coord_checked: "Category:Miramichi, New Brunswick (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Miramichi,_New_Brunswick, 2026-11-17", photo: {"file": "images/places/ca-miramichi.jpg", "width": 800, "height": 532, "author": "Gabriel Picard", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AMiramichi_River_08-2025.jpg", "alt_en": "The Miramichi River at Miramichi", "alt_zh": "米拉米奇市的米拉米奇河"} },
  { id: "ca-creignish", country: "ca", name: "Creignish, Cape Breton", name_zh: "布雷顿角 · 克雷格尼什", lat: 45.729789, lon: -61.458892, place_type: "original", note: "圣乔治湾岸边一个零散的盖尔语教区，就在坎索堤道北边。《主教的人》里，多年替教区悄悄掩盖神父丑闻的邓肯·麦卡斯基尔神父，被派回他长大的地方附近的这个教区，并被叮嘱低调行事。教区教堂俯瞰着海湾", note_en: "A scattered Gaelic parish on the shore of St George's Bay, just north of the Canso Causeway. In The Bishop's Man, Father Duncan MacAskill, who has spent years quietly covering up priests' abuse for his diocese, is sent back to this parish near where he grew up and told to keep his head down. The parish church looks out over the bay", coord_checked: "Category:Creignish (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Creignish, 2026-11-17", photo: {"file": "images/places/ca-creignish.jpg", "width": 800, "height": 600, "author": "Larry from Charlottetown, PEI, Canada", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File%3ACeltic_Shores_Coastal_Trail%2C_Creignish%2C_Cape_Breton_%2829276693015%29.jpg", "alt_en": "The coastal trail at Creignish on St George's Bay", "alt_zh": "圣乔治湾边克雷格尼什的海岸步道"} },
  { id: "ca-dtes", country: "ca", name: "Downtown Eastside, Vancouver", name_zh: "温哥华 · 市中心东区", lat: 49.281389, lon: -123.099722, place_type: "original", note: "温哥华最老的街区，以缅街和黑斯廷斯街口为中心，长期是全城最穷的地方，也收留无处可去的人。《五个小印第安人》里，五个从温哥华岛外一座小岛上的寄宿学校出来的原住民年轻人，20 世纪 60 年代被放到这里，努力重建生活。如今这里也有卡内基中心和活跃的社区组织", note_en: "Vancouver's oldest neighbourhood, around Main and Hastings, long the city's poorest and a refuge for people with nowhere else to go. In Five Little Indians, five young survivors of a residential school on an island off Vancouver Island are released here in the 1960s and try to build lives. Today it is also home to the Carnegie Centre and a strong community of activists", coord_checked: "Category:Downtown Eastside (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Downtown_Eastside, 2026-11-17", photo: {"file": "images/places/ca-dtes.jpg", "width": 800, "height": 472, "author": "Unknown author", "license": "Public domain", "license_url": "https://creativecommons.org/publicdomain/mark/1.0/", "source": "https://commons.wikimedia.org/wiki/File%3AOld_streetcars_at_the_Corner_of_Hastings_and_Main%2C_Vancouver.jpg", "alt_en": "Streetcars at the corner of Hastings and Main, Vancouver, in the early 1900s", "alt_zh": "20 世纪初温哥华黑斯廷斯街与缅街口的有轨电车"} },
  { id: "ca-halifax-waterfront", country: "ca", name: "Halifax waterfront", name_zh: "哈利法克斯海滨", lat: 44.64577, lon: -63.56921, place_type: "original", note: "新斯科舍首府的港口，两百年来既是英国海军的港口，也是寻求自由的人上岸的地方。《华盛顿·布莱克》里，从巴巴多斯种植园逃出的瓦什在哈利法克斯定居，在岸边画海洋生物，结识了博物学家戈夫和他的女儿坦娜，和他们一起梦想建一座“海洋之屋”。如今海滨步道经过海事博物馆和 21 号码头", note_en: "The harbourfront of Nova Scotia's capital, for two centuries a port of the British navy and of people seeking freedom. In Washington Black, Wash, who escaped slavery on a Barbados plantation, settles in Halifax, draws the sea creatures on its shore, and meets the naturalist Goff and his daughter Tanna, with whom he dreams of building an 'ocean house'. The boardwalk now runs past the Maritime Museum and Pier 21", coord_checked: "Category:Halifax Waterfront (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Halifax_Waterfront, 2026-11-17", photo: {"file": "images/places/ca-halifax-waterfront.jpg", "width": 800, "height": 600, "author": "WabbitWanderer from London, Canada", "license": "CC BY-SA 2.0", "license_url": "https://creativecommons.org/licenses/by-sa/2.0", "source": "https://commons.wikimedia.org/wiki/File%3AConstruction_on_the_Halifax_Waterfront_in_August_2019.jpg", "alt_en": "The Halifax waterfront seen from the harbour", "alt_zh": "从港内看哈利法克斯海滨"} },
  { id: "ca-gander", country: "ca", name: "Gander International Airport", name_zh: "甘德国际机场", lat: 48.9475, lon: -54.56, place_type: "original", note: "20 世纪 30 年代建成，供跨大西洋航班加油。2001 年 9 月 11 日美国领空关闭，38 架客机降落在这里，约 6700 名乘客被一座只有一万人左右的小镇接待了好几天。《世界来到小镇的那天》讲了这个故事，后来改编成音乐剧《来自远方》；镇上有纪念那一周的纪念物", note_en: "Built in the 1930s as a refuelling stop for transatlantic flights. On 11 September 2001, when American airspace closed, 38 airliners landed here and some 6,700 passengers were taken in for days by a town of about 10,000. The Day the World Came to Town tells the story, which became the musical Come From Away; the town has a memorial to that week", coord_checked: "Category:Gander International Airport (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Gander_International_Airport, 2026-11-17", photo: {"file": "images/places/ca-gander.jpg", "width": 800, "height": 602, "author": "Samuell", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AGander_International_terminal_interior.jpg", "alt_en": "The international lounge of Gander airport", "alt_zh": "甘德机场的国际候机厅"} },
  { id: "ca-yellowknife", country: "ca", name: "Yellowknife", name_zh: "耶洛奈夫", lat: 62.4665, lon: -114.349, place_type: "original", note: "西北地区首府，在大奴湖北岸，20 世纪 30 年代作为金矿镇建立。《深夜电台》写的是 1975 年这里的一个小电台，一群员工等着电视的到来，又为麦肯齐河谷输油管道争论不休。老城的船屋和飞行员纪念碑俯瞰着海湾", note_en: "The capital of the Northwest Territories, on the north shore of Great Slave Lake, founded as a gold-mining town in the 1930s. Late Nights on Air is set at its small CBC radio station in 1975, among the staff who wait for television and argue over the Mackenzie Valley Pipeline. The Old Town's houseboats and the Bush Pilots Monument look over the bay", coord_checked: "Category:Wildcat Cafe (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Wildcat_Cafe, 2026-11-17", photo: {"file": "images/places/ca-yellowknife.jpg", "width": 800, "height": 533, "author": "GoToVan", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File%3AYellowknife_Old_Town.jpg", "alt_en": "Old Town, Yellowknife", "alt_zh": "耶洛奈夫老城"} },
  { id: "ca-grouard", country: "ca", name: "Grouard, Lesser Slave Lake", name_zh: "小奴湖 · 格鲁阿尔", lat: 55.5203, lon: -116.161, place_type: "original", note: "小奴湖西头的克里族和梅蒂人村落，当年是热闹的传教站和骑警哨所。《迈克太太》大致取材于凯瑟琳·玛丽·弗拉尼根的经历，写一个十六岁的波士顿姑娘 1907 年嫁给一名骑警，随他去北方各个哨所，这里就是其中之一。村里的传教站教堂至今还在", note_en: "A Cree and Métis village at the west end of Lesser Slave Lake, once a busy mission and Mounted Police post. Mrs. Mike, based loosely on the life of Katherine Mary Flannigan, follows a sixteen-year-old Boston girl who marries a Mountie in 1907 and comes to his northern posts, here among them. Its mission church still stands", coord_checked: "Category:Grouard (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Grouard, 2026-11-17" },
  { id: "ca-moose-factory", country: "ca", name: "Moose Factory and Moosonee", name_zh: "穆斯工厂与穆索尼", lat: 51.258333, lon: -80.6, place_type: "original", note: "隔着穆斯河相望的两个克里族社区，靠近詹姆斯湾，只能坐火车或飞机到达。哈德逊湾公司 1673 年在穆斯工厂岛上建了贸易站。《穿越黑云杉》里，丛林飞行员威尔·伯德昏迷躺在岛上的医院里，侄女安妮对他讲她在多伦多、蒙特利尔和纽约度过的一年。博伊登的第一部小说《三日之路》里，泽维尔·伯德和朋友以利亚在穆斯工厂周围的林子里长大，后来一同去打第一次世界大战，当了狙击手", note_en: "Two Cree communities facing each other across the Moose River near James Bay, reached only by train or plane. The Hudson's Bay Company built a post on Moose Factory island in 1673. In Through Black Spruce the bush pilot Will Bird lies in a coma in the island's hospital while his niece Annie tells him of her year in Toronto, Montreal and New York. In Boyden's first novel, Three Day Road, Xavier Bird and his friend Elijah grow up in the bush around Moose Factory before going to the First World War as snipers", coord_checked: "Category:Moose Factory (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Moose_Factory, 2026-11-17", offshore_island: true, photo: {"file": "images/places/ca-moose-factory.jpg", "width": 800, "height": 536, "author": "P199", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3AMoose_Factory_Centennial_Park.JPG", "alt_en": "Centennial Park on Moose Factory island, with its old graves and Hudson's Bay Company buildings", "alt_zh": "穆斯工厂岛上的百年公园，有老墓地和哈德逊湾公司的老房子"} },
  { id: "ca-laurence-home", country: "ca", name: "Margaret Laurence Home, Neepawa", name_zh: "尼帕瓦 · 玛格丽特·劳伦斯故居", lat: 50.23212, lon: -99.46781, place_type: "pilgrimage", note: "玛格丽特·劳伦斯少女时代在尼帕瓦住过的砖房。她把这座草原小镇写成了马纳瓦卡，《石头天使》《上帝的玩笑》《占卜者》都以它为背景。故居现为博物馆，陈列着她的打字机和书，她本人葬在镇上的墓地", book_ids: ["the-diviners"], note_en: "The brick house where Margaret Laurence lived as a girl in Neepawa, the prairie town she turned into Manawaka, the setting of The Stone Angel, A Jest of God and The Diviners. It is now a museum with her typewriter and books, and she is buried in the town cemetery", coord_checked: "Category:Margaret Laurence House (Wikimedia Commons) — https://commons.wikimedia.org/wiki/Category:Margaret_Laurence_House, 2026-11-17", photo: {"file": "images/places/ca-laurence-home.jpg", "width": 800, "height": 600, "author": "Amqui", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3ANeepawa_-_Margaret_Laurence_House_3.JPG", "alt_en": "The Margaret Laurence Home in Neepawa", "alt_zh": "尼帕瓦的玛格丽特·劳伦斯故居"} },
  { id: "ca-raymore", country: "ca", name: "Raymore Park, Weston", name_zh: "韦斯顿 · 雷莫尔公园", lat: 43.69665, lon: -79.515067, place_type: "original", note: "1954 年 10 月 15 日，飓风“黑兹尔”引发的洪水冲走了亨伯河边雷莫尔路上的房子，淹死 35 人；这条街再也没有重建，如今是河边的这座公园。《漂泊手记》里，大屠杀幸存者的儿子本，眼看着自家在韦斯顿的房子毁于同一场洪水，后来成了研究天气史的学者。重建的人行桥上有纪念牌", note_en: "On 15 October 1954 Hurricane Hazel's floods swept away the houses of Raymore Drive on the Humber River and drowned 35 people; the street was never rebuilt and is now this riverside park. In Fugitive Pieces Ben, the son of Holocaust survivors, sees his family's home in Weston wrecked by the same flood, and later becomes a historian of weather. A plaque on the rebuilt footbridge remembers them", coord_checked: "Raymore Park (Wikipedia) — https://en.wikipedia.org/wiki/Raymore_Park, 2026-11-17", photo: {"file": "images/places/ca-raymore.jpg", "width": 800, "height": 532, "author": "Risker", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3ALooking_west_to_Raymore_Park_-1.JPG", "alt_en": "Raymore Park and the Humber River, looking west", "alt_zh": "向西望雷莫尔公园和亨伯河"} },
  // —— 11-24: second pack, the two books left out of the first (tools/content/batches/add_ca2.py) ——
  { id: "ca-quebec-city", country: "ca", name: "Quebec City", name_zh: "魁北克城", lat: 46.81388889, lon: -71.20805556, place_type: "original", note: "魁北克省省会，玛丽-克莱尔·布莱 1939 年生在这里一个工人家庭。《埃马纽埃尔生命中的一季》（1965）1966 年获美第奇奖，故事发生在魁北克乡间一座穷苦的农场，小说没有点出地名，所以这本书挂在这里", note_en: "Capital of the province of Quebec, where Marie-Claire Blais was born in 1939 into a working-class family. A Season in the Life of Emmanuel (1965), which won the Prix Médicis in 1966, is set on a poor farm in rural Quebec that the novel never names, so the book hangs here", coord_checked: "Quebec City (English Wikipedia, article coordinates) — https://en.wikipedia.org/wiki/Quebec_City, 2026-11-24" },
  { id: "ca-algoma", country: "ca", name: "Algoma District, Ontario", name_zh: "阿尔戈马区，安大略省", lat: 48.0, lon: -84.5, place_type: "original", note: "安大略省东北部、加拿大地盾上一片湖泊河流纵横的林区。玛丽安·恩格尔获总督文学奖的小说《熊》（1976）就设在这里，在一座偏远湖泊中虚构的小岛庄园上。图钉标在这个区的位置，不是那座岛", note_en: "Wooded district of lakes and rivers in north-eastern Ontario, on the Canadian Shield. Marian Engel's Bear (1976), which won the Governor General's Award, is set here, on an invented island estate on a remote lake. The pin is the district's own point, not the island", coord_checked: "Algoma District (English Wikipedia, article coordinates) — https://en.wikipedia.org/wiki/Algoma_District, 2026-11-24" },
  // —— 11-28 Canada rule-v2 re-check, batch 1: Atlantic Canada (add_ca_v2_1128_1.py) ——
  { id: "ca-new-waterford", country: "ca", name: "New Waterford, Cape Breton", name_zh: "新沃特福德（布雷顿角）", lat: 46.25222, lon: -60.09389, place_type: "original", note: "布雷顿角岛大西洋岸边的老煤矿镇，在悉尼东北，早先叫巴拉舒瓦湾；十九世纪五十年代起周围就开采煤炭，最后一座矿 2001 年关闭。安-玛丽·麦克唐纳的父亲是新沃特福德人，当年下矿挣学费读完了大学；她的《跪下》（1996）一开头就是这座小镇月夜的一张“照片”：矿井、一排排矿工房子，还有派珀一家在水街上的家", note_en: "Former coal-mining town on the Atlantic shore of Cape Breton Island, north-east of Sydney, once called Barrachois Cove; coal was dug around it from the 1850s, and its last mine closed in 2001. Ann-Marie MacDonald's father came from New Waterford and worked in the mines to put himself through university; her Fall on Your Knees (1996) begins with a picture of the town by moonlight, the collieries and the rows of miners' houses, and the Piper family's house on Water Street", coord_checked: "en.wikipedia \"New Waterford, Nova Scotia\" coordinates — https://en.wikipedia.org/wiki/New_Waterford,_Nova_Scotia, 2026-11-28", photo: {"file": "images/places/ca-new-waterford.jpg", "width": 800, "height": 533, "author": "Ken Heaton", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:20161001_Low_Point_Lighthouse_Aerial_2.jpg", "alt_en": "Low Point lighthouse at New Victoria, on the Cape Breton coast next to New Waterford, from the air", "alt_zh": "从空中看新沃特福德旁边海岸上的洛波因特灯塔（新维多利亚）"} },
  { id: "ca-scots-bay", country: "ca", name: "Scots Bay, Nova Scotia", name_zh: "斯科茨湾（新斯科舍）", lat: 45.30056, lon: -64.395, place_type: "original", note: "芬迪湾边国王县的小村，靠近斯普利特角，1764 年有人定居；靠打鱼、种地、伐木和造船为生，最后一艘纵帆船 1918 年在这里下水。艾米·麦凯搬进这里一座老农舍，才知道它从前被叫作“接生屋”：二十世纪初，村里的接生婆在这里接下了全村的孩子。这段往事成了她的第一部小说《接生屋》（2006），故事就发生在斯科茨湾", note_en: "Small Bay of Fundy community in Kings County, near Cape Split, settled in 1764; it lived by fishing, farming, logging and shipbuilding, and its last schooner was launched in 1918. Ami McKay moved into an old farmhouse here and learned that it had been known as the birth house, where a local midwife delivered the village's babies in the early twentieth century; that history became her first novel, The Birth House (2006), set in Scots Bay", coord_checked: "en.wikipedia \"Scots Bay, Nova Scotia\" coordinates — https://en.wikipedia.org/wiki/Scots_Bay,_Nova_Scotia, 2026-11-28", photo: {"file": "images/places/ca-scots-bay.jpg", "width": 800, "height": 533, "author": "Quintin Soloviev", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0", "source": "https://commons.wikimedia.org/wiki/File:Scots_Bay,_Nova_Scotia.jpg", "alt_en": "Scots Bay on the Bay of Fundy from the air: farms, a white church and the shore", "alt_zh": "从空中看芬迪湾边的斯科茨湾：农田、白色教堂和海岸"} },
  { id: "ca-st-johns", country: "ca", name: "St. John's, Newfoundland", name_zh: "圣约翰斯（纽芬兰）", lat: 47.5614, lon: -52.7119, place_type: "original", note: "纽芬兰与拉布拉多省首府，在阿瓦隆半岛东端，是北美最东的城市。韦恩·约翰斯顿的《未竟之梦的殖民地》（1998）里，少年乔伊·斯莫尔伍德在圣约翰斯贫穷的“坡顶”长大，记者希拉·菲尔丁在这座城的街巷里游走；凯瑟琳·温特的《安娜贝尔》（2010）里，韦恩·布莱克离开拉布拉多海岸，来到母亲的故乡圣约翰斯", note_en: "Capital of Newfoundland and Labrador, on the eastern tip of the Avalon Peninsula, the easternmost city in North America. In Wayne Johnston's The Colony of Unrequited Dreams (1998) the young Joey Smallwood grows up poor on the Brow in St. John's, and the journalist Sheilagh Fielding walks its streets; in Kathleen Winter's Annabel (2010) Wayne Blake leaves the Labrador coast for St. John's, the city his mother came from", coord_checked: "en.wikipedia \"St. John's, Newfoundland and Labrador\" coordinates — https://en.wikipedia.org/wiki/St._John%27s,_Newfoundland_and_Labrador, 2026-11-28", photo: {"file": "images/places/ca-st-johns.jpg", "width": 800, "height": 533, "author": "Jcmurphy", "license": "Public domain", "license_url": "https://en.wikipedia.org/wiki/Public_domain", "source": "https://commons.wikimedia.org/wiki/File:City_of_St._John%27s.jpg", "alt_en": "St. John's harbour and the city from Signal Hill", "alt_zh": "从信号山望圣约翰斯港和城区"} },
  { id: "ca-trinity", country: "ca", name: "Trinity, Trinity Bay", name_zh: "三一镇（三一湾）", lat: 48.37556, lon: -53.39472, place_type: "film_location", adaptation: {"title": "The Shipping News", "year": 2001, "kind": "电影"}, scene: "莱塞·霍尔斯道姆 2001 年把安妮·普鲁的《船讯》拍成电影，凯文·史派西主演，大半在纽芬兰三一湾的三一湾角一带拍摄；三一镇是外景地之一，往南几公里的新博纳旺蒂尔演了书里的基利克-克劳镇。普鲁坚持电影必须在纽芬兰拍。书里的基利克-克劳和奎尔角都是虚构的：纽约州北部的报社小职员奎尔，父母双双自杀，妻子佩塔尔跟别的男人出车祸死了；姑妈阿格尼丝·哈姆劝他带着两个女儿回到祖先的纽芬兰，搬进奎尔角上一座荒废的老屋。他在小镇报纸《海鸥报》写车祸，也写港口船只进出的“船讯”，这一栏慢慢成了他的招牌；他交了朋友，和本地寡妇韦薇·普劳斯走到一起，也慢慢知道了祖先阴暗的往事。摘句不能挂在影视取景地上，所以这本书通过这部电影出现在这里", book_ids: ["the-shipping-news"], scene_en: "Lasse Hallström's 2001 film of Annie Proulx's The Shipping News, with Kevin Spacey, was shot largely in Trinity Bight on Trinity Bay, Newfoundland; Trinity is one of its locations, and New Bonaventure, a few kilometres south, stood in for the novel's Killick-Claw. Proulx held out for the film to be made in Newfoundland. The book's Killick-Claw and Quoyle's Point are invented: Quoyle, a newspaperman from upstate New York, loses his parents to a double suicide and his wife Petal to a car crash with another man; his aunt Agnis Hamm talks him into taking his two daughters to the family's Newfoundland, to the abandoned house on Quoyle's Point. On the local paper, the Gammy Bird, he covers car wrecks and the shipping news, the comings and goings of ships in port, which becomes his signature column; he makes friends, finds his way to the widow Wavey Prowse, and learns the dark secrets of his ancestors. Excerpts cannot be hung on a film location, so the book is shown here through the film", coord_checked: "en.wikipedia \"Trinity, Newfoundland and Labrador\" coordinates — https://en.wikipedia.org/wiki/Trinity,_Newfoundland_and_Labrador, 2026-11-28", photo: {"file": "images/places/ca-trinity.jpg", "width": 800, "height": 495, "author": "Wikidedia11001", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Lester-Garland_Premises_and_the_Rising_Tide_Theatre_(Trinity,_Trinity_Bight,_Newfoundland_and_Labrador,_Canada).jpg", "alt_en": "The red Lester-Garland Premises and the Rising Tide Theatre on the harbour at Trinity", "alt_zh": "三一镇港边红色的莱斯特-加兰商栈和涨潮剧院"} },
  // —— 11-28 Canada rule-v2 re-check, batch 2: Quebec (add_ca_v2_1128_2.py) ——
  { id: "ca-saint-laurent", country: "ca", name: "Saint-Laurent Boulevard and the Red Light, Montreal", name_zh: "蒙特利尔 · 圣洛朗大道与红灯区", lat: 45.509873, lon: -73.563768, place_type: "original", note: "“大街”是把蒙特利尔分成东西两半的那条长街，它和圣凯瑟琳街的路口，就是老红灯区的中心，从前满是夜总会和妓院。在蒙特利尔长大的希瑟·奥尼尔把《给小罪犯的摇篮曲》（2006）放在这一带：十二岁的贝比和父亲朱尔斯在附近的廉价房间之间搬来搬去", note_en: "The Main, the long street that divides Montreal into east and west, and its crossing with Saint Catherine Street, the heart of the old Red Light district of cabarets and brothels. Heather O'Neill, who grew up in Montreal, set her Lullabies for Little Criminals (2006) in this district: twelve-year-old Baby and her father Jules drift between cheap rooms around it", coord_checked: "en.wikipedia \"Red-Light District, Montreal\" coordinates (Saint Laurent Boulevard at Saint Catherine Street) — https://en.wikipedia.org/wiki/Red-Light_District,_Montreal, 2026-11-28", photo: {"file": "images/places/ca-saint-laurent.jpg", "width": 800, "height": 600, "author": "Jeangagnon", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Boulevard_Saint-Laurent_et_rue_Sainte-Catherine_Ouest.JPG", "alt_en": "The corner of Saint-Laurent Boulevard and Saint Catherine Street in Montreal", "alt_zh": "蒙特利尔圣洛朗大道和圣凯瑟琳街的路口"} },
  { id: "ca-saint-henri", country: "ca", name: "Saint-Henri, Montreal", name_zh: "蒙特利尔 · 圣亨利区", lat: 45.47716, lon: -73.58651, place_type: "original", note: "蒙特利尔西南部讲法语的工人街区，南边以拉欣运河为界。加布丽埃勒·罗伊把《锡笛》（法文名《二手的幸福》，1945）放在 1940 年春天的这些街道上；书中对贫穷毫不粉饰的描写赢得了费米娜奖，常被认为为魁北克的“寂静革命”做了铺垫", note_en: "Working-class French-Canadian district of south-west Montreal, bounded on the south by the Lachine Canal. Gabrielle Roy set Bonheur d'occasion (1945; The Tin Flute) in its streets in the spring of 1940; the stark portrait of poverty here won the Prix Femina and is often said to have helped prepare Quebec's Quiet Revolution", coord_checked: "en.wikipedia \"Saint-Henri, Montreal\" coordinates — https://en.wikipedia.org/wiki/Saint-Henri,_Montreal, 2026-11-28", photo: {"file": "images/places/ca-saint-henri.jpg", "width": 800, "height": 598, "author": "BAnQ Vieux-Montréal archives", "license": "Public domain", "license_url": "https://en.wikipedia.org/wiki/Public_domain", "source": "https://commons.wikimedia.org/wiki/File:Saint-Henri,_Montreal_-_La_rue_Notre-Dame.jpg", "alt_en": "Rue Notre-Dame in Saint-Henri, Montreal, in an early twentieth-century photograph", "alt_zh": "二十世纪初照片里蒙特利尔圣亨利区的圣母街"} },
  { id: "ca-knowlton", country: "ca", name: "Knowlton, Quebec", name_zh: "魁北克 · 诺尔顿", lat: 45.21722, lon: -72.51861, place_type: "prototype", prototype_of: "路易丝·彭妮“加马什探长”系列推理小说里虚构的三松村，就在佛蒙特边界以北。彭妮住在东镇布罗姆湖畔的诺尔顿，这里最常被说成三松村的原型，村里书店的原型是布罗姆湖书店；不过彭妮本人说，三松村并不是照着诺尔顿写的，而是从东镇好几个村子里长出来的", prototype_of_en: "Three Pines, the invented village of Louise Penny's Chief Inspector Gamache mysteries, set just north of the Vermont border. Penny lives in Knowlton, on Brome Lake in the Eastern Townships, and it is the village most often named as Three Pines' model, with Brome Lake Books as the model for the village bookshop; Penny herself says Three Pines is not a copy of Knowlton but grew out of several Townships villages", coord_checked: "en.wikipedia \"Knowlton, Quebec\" coordinates — https://en.wikipedia.org/wiki/Knowlton,_Quebec, 2026-11-28", photo: {"file": "images/places/ca-knowlton.jpg", "width": 800, "height": 599, "author": "Hayden Soloviev", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0", "source": "https://commons.wikimedia.org/wiki/File:%E2%81%A8Knowlton%E2%81%A9,_%E2%81%A8Quebec%E2%81%A9,_%E2%81%A8Canada%E2%81%A9.jpg", "alt_en": "Knowlton village and Brome Lake from the air", "alt_zh": "从空中看诺尔顿村和布罗姆湖"} },
  // —— 11-28 Canada rule-v2 re-check, batch 3: Toronto (add_ca_v2_1128_3.py) ——
  { id: "ca-bloor-viaduct", country: "ca", name: "Prince Edward Viaduct (Bloor Street Viaduct)", name_zh: "爱德华王子高架桥（布卢尔街高架桥）", lat: 43.67528, lon: -79.36389, place_type: "original", note: "把布卢尔街和地铁架过当河谷的钢拱桥，1918 年通车。迈克尔·翁达杰的《身着狮皮》（1987）透过建桥的移民工人讲这座桥的修建，其中就有马其顿桥工尼古拉斯·泰梅尔科夫；2009 年小说里的一段文字被立在高架桥边，成为“加拿大文学书签计划”在这条全国文学路线上的第一块牌子", note_en: "The steel-arch bridge that carries Bloor Street and the subway across the Don Valley, opened in 1918. Michael Ondaatje's In the Skin of a Lion (1987) tells the story of its building through the immigrant workers who built it, among them the Macedonian bridge-worker Nicholas Temelcoff; in 2009 a passage from the novel was set up at the viaduct, the first Project Bookmark Canada plaque on the country's literary trail", coord_checked: "en.wikipedia \"Prince Edward Viaduct\" coordinates — https://en.wikipedia.org/wiki/Prince_Edward_Viaduct, 2026-11-28", photo: {"file": "images/places/ca-bloor-viaduct.jpg", "width": 800, "height": 600, "author": "Paul dexxus", "license": "CC BY 3.0", "license_url": "https://creativecommons.org/licenses/by/3.0", "source": "https://commons.wikimedia.org/wiki/File:Prince_Edward_Viaduct.jpg", "alt_en": "The steel arches of the Prince Edward Viaduct over the Don Valley, in autumn", "alt_zh": "秋天当河谷上爱德华王子高架桥的钢拱"} },
  { id: "ca-high-park", country: "ca", name: "High Park, Toronto", name_zh: "多伦多 · 海伊公园", lat: 43.646821, lon: -79.462996, place_type: "original", note: "多伦多最大的公园，在城西，有树林、谷地和掷弹兵池。安德烈·亚历克西斯的《十五只狗》（2015）里，被赫尔墨斯和阿波罗赋予人类语言的十五只狗从兽医诊所逃出来，就在这里建起了它们自己的新社会", note_en: "Toronto's largest park, in the west of the city, with woods, ravines and Grenadier Pond. In André Alexis's Fifteen Dogs (2015) the fifteen dogs whom Hermes and Apollo give human language escape from a veterinary clinic and set up their own new society here", coord_checked: "en.wikipedia \"High Park\" coordinates — https://en.wikipedia.org/wiki/High_Park, 2026-11-28", photo: {"file": "images/places/ca-high-park.jpg", "width": 800, "height": 600, "author": "Diego Torres Silvestre", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File:Grenadier_Pond_(61904034).jpg", "alt_en": "Autumn trees over Grenadier Pond in High Park, Toronto", "alt_zh": "多伦多海伊公园掷弹兵池边的秋树"} },
  { id: "ca-elgin-theatre", country: "ca", name: "Elgin Theatre, Toronto", name_zh: "多伦多 · 埃尔金剧院", lat: 43.65306, lon: -79.37917, place_type: "original", note: "央街上的埃尔金与冬园剧院是上下叠在一起的两座爱德华时代剧院，埃尔金在下层。《第十一站》（2014）就从这里开场：演出《李尔王》时，演员亚瑟·利安德心脏病发，死在舞台上；同一个夜里，一场流感大流行开始了，旧世界将就此终结", note_en: "The lower house of the Elgin and Winter Garden Theatres on Yonge Street, a stacked pair of Edwardian theatres. Station Eleven (2014) opens here: during a production of King Lear the actor Arthur Leander dies on stage of a heart attack, on the night a flu pandemic begins that will end the old world", coord_checked: "en.wikipedia \"Elgin and Winter Garden Theatres\" coordinates — https://en.wikipedia.org/wiki/Elgin_and_Winter_Garden_Theatres, 2026-11-28", photo: {"file": "images/places/ca-elgin-theatre.jpg", "width": 800, "height": 600, "author": "Geo Swan", "license": "CC0", "license_url": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Front_Facade_for_the_Elgin_and_Winter_Gardens_theatres,_Yonge_Street,_Toronto_-e.jpg", "alt_en": "The front of the Elgin and Winter Garden Theatres on Yonge Street, Toronto", "alt_zh": "多伦多央街上埃尔金与冬园剧院的正门"} },
  { id: "ca-toronto-islands", country: "ca", name: "Toronto Islands", name_zh: "多伦多群岛", lat: 43.62083, lon: -79.37861, place_type: "original", note: "隔着港湾与多伦多市中心相望的一串小岛，要坐渡轮去，岛上是公园，沃兹岛和阿尔冈昆岛上还有一小片村舍。玛格丽特·阿特伍德的《强盗新娘》（1993）里，温柔又“新时代”的查丽丝就住在岛上一座破旧的小屋里，从那里望去，城市仿佛浮在晨雾之上", note_en: "The chain of small islands across the harbour from downtown Toronto, reached by ferry, with parkland and a small community of cottages on Ward's and Algonquin islands. In Margaret Atwood's The Robber Bride (1993) the gentle, New Age Charis lives in a ramshackle cottage on the Island, from where the city seems to float on the morning mist", coord_checked: "en.wikipedia \"Toronto Islands\" coordinates — https://en.wikipedia.org/wiki/Toronto_Islands, 2026-11-28", photo: {"file": "images/places/ca-toronto-islands.jpg", "width": 800, "height": 530, "author": "shankar s.", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File:A_lovely_cottage_on_Ward%27s_Island_(27864695136).jpg", "alt_en": "A cottage among the trees on Ward's Island, one of the Toronto Islands", "alt_zh": "多伦多群岛沃兹岛上树丛间的一座小屋"} },
  { id: "ca-erindale", country: "ca", name: "Erindale College (University of Toronto Mississauga)", name_zh: "伊林代尔学院（多伦多大学密西沙加校区）", lat: 43.54833, lon: -79.66333, place_type: "prototype", prototype_of: "约瑟夫·什克沃雷茨基《人类灵魂工程师》（1977）里多伦多附近的伊登维尔学院：流亡的捷克作家丹尼·斯米日茨基在那里教美国文学。什克沃雷茨基和他的叙述者一样在 1968 年离开捷克斯洛伐克，他在多伦多大学的伊林代尔学院教英文，那里就是今天的多伦多大学密西沙加校区", prototype_of_en: "Edenvale College, near Toronto, where Danny Smiřický, Czech writer in exile, teaches American literature in Josef Škvorecký's The Engineer of Human Souls (1977). Škvorecký, who left Czechoslovakia in 1968 like his narrator, taught English at Erindale College of the University of Toronto, now the University of Toronto Mississauga", coord_checked: "en.wikipedia \"University of Toronto Mississauga\" coordinates — https://en.wikipedia.org/wiki/University_of_Toronto_Mississauga, 2026-11-28", photo: {"file": "images/places/ca-erindale.jpg", "width": 800, "height": 495, "author": "Siqbal at English Wikipedia", "license": "Public domain", "license_url": "https://en.wikipedia.org/wiki/Public_domain", "source": "https://commons.wikimedia.org/wiki/File:University_of_Toronto_at_Mississauga.JPG", "alt_en": "A building on the University of Toronto Mississauga campus, the former Erindale College", "alt_zh": "多伦多大学密西沙加校区（原伊林代尔学院）的一座楼"} },
  // —— 11-28 Canada rule-v2 re-check, batch 4: Ontario (add_ca_v2_1128_4.py) ——
  { id: "ca-orillia", country: "ca", name: "Orillia, Ontario", name_zh: "安大略 · 奥里利亚", lat: 44.60417, lon: -79.42389, place_type: "prototype", prototype_of: "斯蒂芬·里柯克《小镇艳阳录》（1912）里维萨诺蒂湖畔的小镇马里波萨。里柯克是从他在库奇钦湖畔奥里利亚的岁月里取的材，书中许多人物也取自奥里利亚的镇民，这些速写最初在《蒙特利尔星报》连载时，人名只是稍加改动；不过里柯克自己说，马里波萨其实是七八十个小镇。奥里利亚至今自称“阳光之城”，他的夏日别墅如今是里柯克博物馆，属国家历史遗址", prototype_of_en: "Mariposa, the little town on Lake Wissanotti in Stephen Leacock's Sunshine Sketches of a Little Town (1912). Leacock drew it from his years in Orillia, on Lake Couchiching, and many of its characters from Orillia people, whose names were only thinly disguised when the sketches first ran in the Montreal Star; Leacock himself wrote that Mariposa was seventy or eighty towns. Orillia still calls itself the Sunshine City, and his summer house is now the Leacock Museum, a National Historic Site", coord_checked: "en.wikipedia \"Orillia\" coordinates — https://en.wikipedia.org/wiki/Orillia, 2026-11-28", photo: {"file": "images/places/ca-orillia.jpg", "width": 800, "height": 600, "author": "Jcart1534", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:Stephen_Leacock_House_Orillia.jpg", "alt_en": "Stephen Leacock's summer house in Orillia, now the Leacock Museum", "alt_zh": "奥里利亚的斯蒂芬·里柯克夏日别墅，如今是里柯克博物馆"} },
  { id: "ca-parliament-hill", country: "ca", name: "Parliament Hill, Ottawa", name_zh: "渥太华 · 国会山", lat: 45.42472, lon: -75.69944, place_type: "original", note: "渥太华河上方的山岗，加拿大议会所在地。特里·法利斯的喜剧小说《人算不如天算》（2007）里，心力交瘁的演讲撰稿人丹尼尔·艾迪生在这里辞了职，后来又陪着安格斯·麦克林托克回到这里：这位脾气古怪的工程学教授答应去一个毫无希望的选区挂名参选，结果出乎所有人意料，竟当选了", note_en: "The hill above the Ottawa River where the Parliament of Canada sits. In Terry Fallis's comic novel The Best Laid Plans (2007) the burnt-out speechwriter Daniel Addison quits his job here, and comes back with Angus McLintock, the cranky engineering professor who agreed to run in a hopeless riding and, to everyone's horror, was elected", coord_checked: "en.wikipedia \"Parliament Hill\" coordinates — https://en.wikipedia.org/wiki/Parliament_Hill, 2026-11-28", photo: {"file": "images/places/ca-parliament-hill.jpg", "width": 800, "height": 617, "author": "DXR", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Centre_Block,_Ottawa,_Southeast_view_20170422_1.jpg", "alt_en": "The Centre Block and Peace Tower on Parliament Hill, Ottawa", "alt_zh": "渥太华国会山上的中央大楼和和平塔"} },
  { id: "ca-sainte-marie", country: "ca", name: "Sainte-Marie among the Hurons", name_zh: "休伦人中的圣玛丽", lat: 44.73417, lon: -79.84528, place_type: "original", note: "法国耶稣会在温达特人（休伦人）的土地温达克建的传教站，在今天米德兰附近，1639 年由热罗姆·拉勒芒和让·德·布雷伯夫创建，1649 年废弃；这是安大略第一个欧洲人定居点，如今复建成活态博物馆。约瑟夫·博伊登的《奥伦达》（2013）就发生在传教站那些年的这片土地上；书里的耶稣会士克里斯托夫以布雷伯夫为原型，在温达特战士伯德的村子附近建了一座传教站，不过小说没有把它叫作圣玛丽", note_en: "The French Jesuit mission in Wendake, the country of the Wendat (Huron), near present-day Midland, founded in 1639 by Jérôme Lalemant and Jean de Brébeuf and abandoned in 1649; the first European settlement in Ontario, now a reconstructed living museum. Joseph Boyden's The Orenda (2013) is set in this country in the years of the mission; its Jesuit, Christophe, is modelled on Brébeuf and founds a mission near the village of the Wendat warrior Bird, though the novel does not name it Sainte-Marie", coord_checked: "en.wikipedia \"Sainte-Marie among the Hurons\" coordinates — https://en.wikipedia.org/wiki/Sainte-Marie_among_the_Hurons, 2026-11-28", photo: {"file": "images/places/ca-sainte-marie.jpg", "width": 800, "height": 600, "author": "Pjposullivan", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Sainte-Marie_among_the_Hurons_native_section.JPG", "alt_en": "Reconstructed longhouse and wigwam in the Indigenous section of Sainte-Marie among the Hurons", "alt_zh": "休伦人中的圣玛丽原住民区里复建的长屋和棚屋"} },
  { id: "ca-essex-county", country: "ca", name: "Essex County, Ontario", name_zh: "安大略 · 埃塞克斯县", lat: 42.17528, lon: -82.78056, place_type: "original", note: "安大略西南端圣克莱尔湖和伊利湖之间一片平坦的农业县，杰夫·勒米尔在这里长大。他的图像小说三部曲《埃塞克斯县》（2008–2009）在这里的农田、谷仓和加油站之间，跟着勒伯夫一家和邻居们走过几代人", note_en: "The flat farm county at the south-western tip of Ontario, between Lake St. Clair and Lake Erie, where Jeff Lemire grew up. His graphic trilogy Essex County (2008–2009) follows the LeBeuf family and their neighbours across generations among its fields, barns and gas stations", coord_checked: "en.wikipedia \"Essex County, Ontario\" coordinates — https://en.wikipedia.org/wiki/Essex_County,_Ontario, 2026-11-28", photo: {"file": "images/places/ca-essex-county.jpg", "width": 800, "height": 600, "author": "Andrea_44", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File:The_sky_over_Essex_County_today_(3629337607).jpg", "alt_en": "A straight county road between flat fields under a summer sky in Essex County, Ontario", "alt_zh": "安大略埃塞克斯县平坦田野间一条笔直的乡道，头上是夏日的天空"} }
